package com.serviceconnect.web;

import com.serviceconnect.model.*; import com.serviceconnect.repo.*; import com.serviceconnect.service.*;
import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import jakarta.validation.constraints.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*; import java.util.stream.Collectors;

@RestController @RequestMapping("/api") public class ApiController {
 private final UserAccountRepository users; private final ProviderProfileRepository providers; private final ServiceOfferingRepository offerings; private final AvailabilitySettingsRepository settings; private final AppointmentRepository appointments; private final AppointmentAttachmentRepository attachments; private final InvoiceRepository invoices; private final ProviderDocumentRepository providerDocuments; private final PasswordEncoder encoder; private final CurrentUser current; private final BookingService booking;
 @Value("${app.upload-dir:uploads}") private String uploadDir;
 public ApiController(UserAccountRepository u,ProviderProfileRepository p,ServiceOfferingRepository o,AvailabilitySettingsRepository s,AppointmentRepository a,AppointmentAttachmentRepository at,InvoiceRepository i,ProviderDocumentRepository pd,PasswordEncoder e,CurrentUser c,BookingService b){users=u;providers=p;offerings=o;settings=s;appointments=a;attachments=at;invoices=i;providerDocuments=pd;encoder=e;current=c;booking=b;}
 public record RegisterRequest(@NotBlank String fullName,@Email @NotBlank String email,@NotBlank @Size(min=8) String password,String phone,String role){}
 public record LoginRequest(@Email String email,String password){}
 public record ProviderRequest(String businessName,String description,String category,Integer experienceYears,String qualifications,String address,String city,String state,String pincode,Double latitude,Double longitude,Integer serviceRadiusKm,String deliveryModes){}
 public record ServiceRequest(String title,String category,String description,Double price,Integer durationMinutes){}
 public record SettingsRequest(String workingDays,LocalTime startTime,LocalTime endTime,LocalTime breakStart,LocalTime breakEnd,Integer dailyCapacity,Integer slotDurationMinutes){}
 public record BookingRequest(Long serviceId,String startAt,String problemDescription,String serviceMode,String serviceAddress,Double latitude,Double longitude){}
 public record DecisionRequest(String decision,String note){}
 public record LocationRequest(Double latitude,Double longitude,Boolean online){}

 @PostMapping("/auth/register") @Transactional public Map<String,Object> register(@Valid @RequestBody RegisterRequest r){String role=r.role()==null?"CUSTOMER":r.role().toUpperCase();if(!List.of("CUSTOMER","PROVIDER").contains(role))throw new IllegalArgumentException("Choose CUSTOMER or PROVIDER.");if(users.existsByEmailIgnoreCase(r.email()))throw new IllegalArgumentException("An account with this email already exists.");UserAccount u=new UserAccount();u.fullName=r.fullName();u.email=r.email().toLowerCase();u.passwordHash=encoder.encode(r.password());u.phone=r.phone();u.role=role;u.enabled=true;users.save(u);return Map.of("message","Account created. Please log in.","role",role);}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody LoginRequest r,HttpSession session){UserAccount u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid email or password."));if(!encoder.matches(r.password(),u.passwordHash)||!u.enabled)throw new IllegalArgumentException("Invalid email or password.");session.setAttribute("userId",u.id);return userView(u);}
 @PostMapping("/auth/logout") public Map<String,String> logout(HttpSession s){s.invalidate();return Map.of("message","Logged out.");}
 @GetMapping("/auth/me") public Map<String,Object> me(HttpSession s){return userView(current.require(s));}
 private Map<String,Object> userView(UserAccount u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.id);m.put("fullName",u.fullName);m.put("email",u.email);m.put("phone",u.phone);m.put("role",u.role);providers.findByUserId(u.id).ifPresent(p->{m.put("providerId",p.id);m.put("verificationStatus",p.verificationStatus);});return m;}

 @PostMapping("/provider/profile") @Transactional public Map<String,Object> saveProvider(@RequestBody ProviderRequest r,HttpSession s){UserAccount u=current.requireRole(s,"PROVIDER");ProviderProfile p=providers.findByUserId(u.id).orElseGet(()->{ProviderProfile x=new ProviderProfile();x.user=u;return x;});p.businessName=r.businessName();p.description=r.description();p.category=r.category();p.experienceYears=r.experienceYears()==null?0:r.experienceYears();p.qualifications=r.qualifications();p.address=r.address();p.city=r.city();p.state=r.state();p.pincode=r.pincode();p.latitude=r.latitude();p.longitude=r.longitude();p.serviceRadiusKm=r.serviceRadiusKm()==null?10:r.serviceRadiusKm();p.deliveryModes=r.deliveryModes()==null?"BOTH":r.deliveryModes();if(!p.verificationStatus.equals("PENDING"))p.verificationStatus="PENDING";providers.save(p);booking.getSettings(p);return Map.of("message","Provider profile saved. It is waiting for admin verification.","providerId",p.id,"verificationStatus",p.verificationStatus);}
 @GetMapping("/provider/profile") public Map<String,Object> myProvider(HttpSession s){UserAccount u=current.requireRole(s,"PROVIDER");ProviderProfile p=providers.findByUserId(u.id).orElseThrow(()->new IllegalArgumentException("Complete your provider profile first."));return providerView(p,null);}
 @PostMapping("/provider/location") public Map<String,String> location(@RequestBody LocationRequest r,HttpSession s){UserAccount u=current.requireRole(s,"PROVIDER");ProviderProfile p=providers.findByUserId(u.id).orElseThrow();if(r.latitude()!=null)p.latitude=r.latitude();if(r.longitude()!=null)p.longitude=r.longitude();if(r.online()!=null)p.online=r.online();providers.save(p);return Map.of("message","Location and online status updated.");}
 @PostMapping("/provider/verification-documents") @Transactional public Map<String,Object> uploadProviderDocument(@RequestParam("file") MultipartFile file,HttpSession s)throws IOException{ProviderProfile p=myProviderProfile(s);if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("Choose a document up to 10 MB.");String type=file.getContentType()==null?"":file.getContentType();if(!(type.startsWith("image/")||type.equals("application/pdf")))throw new IllegalArgumentException("Only images and PDF documents are allowed.");String stored=UUID.randomUUID().toString();Path dir=Paths.get(uploadDir).toAbsolutePath().normalize();Files.createDirectories(dir);Files.copy(file.getInputStream(),dir.resolve(stored),StandardCopyOption.REPLACE_EXISTING);ProviderDocument d=new ProviderDocument();d.provider=p;d.originalName=Path.of(file.getOriginalFilename()==null?"document":file.getOriginalFilename()).getFileName().toString();d.storedName=stored;d.contentType=type;d.sizeBytes=file.getSize();providerDocuments.save(d);p.verificationStatus="PENDING";providers.save(p);return Map.of("message","Verification document uploaded.","documentId",d.id);}
 @GetMapping("/admin/providers/{id}/documents") public List<Map<String,Object>> providerDocumentList(@PathVariable Long id,HttpSession s){current.requireRole(s,"ADMIN");return providerDocuments.findByProviderId(id).stream().map(d->Map.of("id",d.id,"name",d.originalName,"contentType",d.contentType)).toList();}
 @GetMapping("/provider-documents/{id}") public ResponseEntity<byte[]> getProviderDocument(@PathVariable Long id,HttpSession s)throws IOException{UserAccount u=current.require(s);ProviderDocument d=providerDocuments.findById(id).orElseThrow();if(!u.role.equals("ADMIN")&&!d.provider.user.id.equals(u.id))throw new IllegalArgumentException("You cannot view this document.");Path path=Paths.get(uploadDir).toAbsolutePath().normalize().resolve(d.storedName);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.contentType)).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+d.originalName.replace("\"","")+"\"").body(Files.readAllBytes(path));}
 @PostMapping("/provider/services") public Map<String,Object> addService(@RequestBody ServiceRequest r,HttpSession s){UserAccount u=current.requireRole(s,"PROVIDER");ProviderProfile p=providers.findByUserId(u.id).orElseThrow();ServiceOffering x=new ServiceOffering();x.provider=p;x.title=r.title();x.category=r.category();x.description=r.description();x.price=r.price()==null?0:r.price();x.durationMinutes=r.durationMinutes()==null?30:r.durationMinutes();return serviceView(offerings.save(x));}
 @PutMapping("/provider/services/{id}") public Map<String,Object> updateService(@PathVariable Long id,@RequestBody ServiceRequest r,HttpSession s){ProviderProfile p=myProviderProfile(s);ServiceOffering x=offerings.findById(id).orElseThrow();if(!x.provider.id.equals(p.id))throw new IllegalArgumentException("Not your service.");x.title=r.title();x.category=r.category();x.description=r.description();x.price=r.price();x.durationMinutes=r.durationMinutes();return serviceView(offerings.save(x));}
 @DeleteMapping("/provider/services/{id}") public Map<String,String> deleteService(@PathVariable Long id,HttpSession s){ProviderProfile p=myProviderProfile(s);ServiceOffering x=offerings.findById(id).orElseThrow();if(!x.provider.id.equals(p.id))throw new IllegalArgumentException("Not your service.");x.active=false;offerings.save(x);return Map.of("message","Service deactivated.");}
 private ProviderProfile myProviderProfile(HttpSession s){return providers.findByUserId(current.requireRole(s,"PROVIDER").id).orElseThrow();}
 @GetMapping("/provider/services") public List<Map<String,Object>> myServices(HttpSession s){return offerings.findByProviderIdAndActiveTrue(myProviderProfile(s).id).stream().map(this::serviceView).toList();}
 @PutMapping("/provider/availability") public Map<String,Object> saveSettings(@RequestBody SettingsRequest r,HttpSession s){ProviderProfile p=myProviderProfile(s);AvailabilitySettings a=booking.getSettings(p);if(r.workingDays()!=null)a.workingDays=r.workingDays();if(r.startTime()!=null)a.startTime=r.startTime();if(r.endTime()!=null)a.endTime=r.endTime();a.breakStart=r.breakStart();a.breakEnd=r.breakEnd();if(r.dailyCapacity()!=null&&r.dailyCapacity()>0&&r.dailyCapacity()<=100)a.dailyCapacity=r.dailyCapacity();if(r.slotDurationMinutes()!=null&&r.slotDurationMinutes()>=10&&r.slotDurationMinutes()<=240)a.slotDurationMinutes=r.slotDurationMinutes();return settingsView(settings.save(a));}
 @GetMapping("/provider/availability") public Map<String,Object> getSettings(HttpSession s){return settingsView(booking.getSettings(myProviderProfile(s)));}

 @GetMapping("/services/search") public List<Map<String,Object>> search(@RequestParam(required=false) String q,@RequestParam(required=false) String category,@RequestParam(required=false) String city,@RequestParam(defaultValue="10") double radiusKm,@RequestParam(required=false) Double lat,@RequestParam(required=false) Double lon,@RequestParam(defaultValue="false") boolean onlineOnly){if(radiusKm<1||radiusKm>500)throw new IllegalArgumentException("Search radius must be between 1 and 500 km.");String term=q==null?"":q.toLowerCase();return offerings.findByActiveTrue().stream().filter(o->"VERIFIED".equals(o.provider.verificationStatus)).filter(o->category==null||o.category!=null&&o.category.equalsIgnoreCase(category)||o.provider.category!=null&&o.provider.category.equalsIgnoreCase(category)).filter(o->city==null||o.provider.city!=null&&o.provider.city.toLowerCase().contains(city.toLowerCase())).filter(o->term.isBlank()||(o.title+" "+o.category+" "+o.description+" "+o.provider.businessName+" "+o.provider.description).toLowerCase().contains(term)).filter(o->!onlineOnly||o.provider.online).map(o->{double d=lat!=null&&lon!=null&&o.provider.latitude!=null&&o.provider.longitude!=null?Geo.km(lat,lon,o.provider.latitude,o.provider.longitude):Double.NaN;Map<String,Object> m=providerView(o.provider,o);m.put("distanceKm",Double.isNaN(d)?null:Math.round(d*10.0)/10.0);return m;}).filter(m->lat==null||lon==null||m.get("distanceKm")!=null&&(Double)m.get("distanceKm")<=radiusKm).sorted(Comparator.comparing(m->m.get("distanceKm")==null?Double.MAX_VALUE:(Double)m.get("distanceKm"))).collect(Collectors.toList());}
 private Map<String,Object> serviceView(ServiceOffering x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.id);m.put("title",x.title);m.put("category",x.category);m.put("description",x.description);m.put("price",x.price);m.put("durationMinutes",x.durationMinutes);m.put("active",x.active);return m;}
 private Map<String,Object> settingsView(AvailabilitySettings a){Map<String,Object> m=new LinkedHashMap<>();m.put("workingDays",a.workingDays);m.put("startTime",a.startTime);m.put("endTime",a.endTime);m.put("breakStart",a.breakStart);m.put("breakEnd",a.breakEnd);m.put("dailyCapacity",a.dailyCapacity);m.put("slotDurationMinutes",a.slotDurationMinutes);return m;}
 private Map<String,Object> providerView(ProviderProfile p,ServiceOffering o){Map<String,Object> m=new LinkedHashMap<>();m.put("providerId",p.id);m.put("businessName",p.businessName);m.put("providerName",p.user.fullName);m.put("phone",p.user.phone);m.put("description",p.description);m.put("category",p.category);m.put("experienceYears",p.experienceYears);m.put("qualifications",p.qualifications);m.put("address",p.address);m.put("city",p.city);m.put("state",p.state);m.put("latitude",p.latitude);m.put("longitude",p.longitude);m.put("deliveryModes",p.deliveryModes);m.put("verificationStatus",p.verificationStatus);m.put("online",p.online);if(o!=null){m.put("serviceId",o.id);m.put("serviceTitle",o.title);m.put("serviceCategory",o.category);m.put("serviceDescription",o.description);m.put("price",o.price);m.put("durationMinutes",o.durationMinutes);}return m;}
 @GetMapping("/services/{id}/slots") public List<Map<String,Object>> slots(@PathVariable Long id,@RequestParam String date){return booking.slots(id,LocalDate.parse(date));}
 @PostMapping("/appointments") @Transactional public Map<String,Object> createBooking(@RequestBody BookingRequest r,HttpSession s){UserAccount customer=current.requireRole(s,"CUSTOMER");ServiceOffering svc=offerings.findById(r.serviceId()).orElseThrow();Appointment a=booking.create(customer,svc,LocalDateTime.parse(r.startAt()),r.problemDescription(),r.serviceMode(),r.serviceAddress(),r.latitude(),r.longitude());return appointmentView(a);}
 @GetMapping("/appointments/mine") public List<Map<String,Object>> customerAppointments(HttpSession s){UserAccount u=current.requireRole(s,"CUSTOMER");return appointments.findByCustomerIdOrderByCreatedAtDesc(u.id).stream().map(this::appointmentView).toList();}
 @GetMapping("/provider/appointments") public List<Map<String,Object>> providerAppointments(HttpSession s){ProviderProfile p=myProviderProfile(s);return appointments.findByProviderIdOrderByStartAtDesc(p.id).stream().map(this::appointmentView).toList();}
 @PostMapping("/appointments/{id}/decision") @Transactional public Map<String,Object> decide(@PathVariable Long id,@RequestBody DecisionRequest r,HttpSession s){ProviderProfile p=myProviderProfile(s);Appointment a=appointments.findById(id).orElseThrow();if(!a.provider.id.equals(p.id))throw new IllegalArgumentException("Not your appointment.");if(!"PENDING".equals(a.status))throw new IllegalArgumentException("This request is no longer pending.");if(a.approvalDeadline.isBefore(LocalDateTime.now())){a.status="EXPIRED";a.providerResponse="Automatically expired after 24 hours without provider approval.";a.updatedAt=LocalDateTime.now();appointments.save(a);return appointmentView(a);}String decision=r.decision().toUpperCase();if(!List.of("APPROVE","REJECT").contains(decision))throw new IllegalArgumentException("Choose APPROVE or REJECT.");a.status=decision.equals("APPROVE")?"APPROVED":"REJECTED";a.providerResponse=r.note();a.updatedAt=LocalDateTime.now();appointments.save(a);if(decision.equals("APPROVE")&&invoices.findByAppointmentId(a.id).isEmpty()){Invoice i=new Invoice();i.appointment=a;i.amount=a.service.price;invoices.save(i);}return appointmentView(a);}
 @PostMapping("/appointments/{id}/cancel") @Transactional public Map<String,Object> cancel(@PathVariable Long id,HttpSession s){UserAccount u=current.require(s);Appointment a=appointments.findById(id).orElseThrow();if(!a.customer.id.equals(u.id)&&!(u.role.equals("PROVIDER")&&a.provider.user.id.equals(u.id)))throw new IllegalArgumentException("You cannot cancel this appointment.");if(!List.of("PENDING","APPROVED").contains(a.status))throw new IllegalArgumentException("This appointment cannot be cancelled.");a.status="CANCELLED";a.updatedAt=LocalDateTime.now();appointments.save(a);return appointmentView(a);}
 private Map<String,Object> appointmentView(Appointment a){Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.id);m.put("verificationCode",a.verificationCode);m.put("customerName",a.customer.fullName);m.put("providerName",a.provider.businessName);m.put("providerPhone",a.provider.user.phone);m.put("serviceTitle",a.service.title);m.put("startAt",a.startAt);m.put("endAt",a.endAt);m.put("problemDescription",a.problemDescription);m.put("serviceMode",a.serviceMode);m.put("serviceAddress",a.serviceAddress);m.put("status",a.status);m.put("providerResponse",a.providerResponse);m.put("approvalDeadline",a.approvalDeadline);m.put("attachments",attachments.findByAppointmentId(a.id).stream().map(x->Map.of("id",x.id,"name",x.originalName,"contentType",x.contentType)).toList());return m;}
 @PostMapping("/appointments/{id}/attachments") @Transactional public Map<String,Object> upload(@PathVariable Long id,@RequestParam("file") MultipartFile file,HttpSession s)throws IOException{UserAccount u=current.require(s);Appointment a=appointments.findById(id).orElseThrow();if(!a.customer.id.equals(u.id)&&!(u.role.equals("PROVIDER")&&a.provider.user.id.equals(u.id)))throw new IllegalArgumentException("You cannot attach files to this appointment.");if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("Choose a file up to 10 MB.");String type=file.getContentType()==null?"":file.getContentType();if(!(type.startsWith("image/")||type.equals("application/pdf")))throw new IllegalArgumentException("Only images and PDF reports are allowed.");String stored=UUID.randomUUID().toString();Path dir=Paths.get(uploadDir).toAbsolutePath().normalize();Files.createDirectories(dir);Files.copy(file.getInputStream(),dir.resolve(stored),StandardCopyOption.REPLACE_EXISTING);AppointmentAttachment at=new AppointmentAttachment();at.appointment=a;at.originalName=Path.of(file.getOriginalFilename()==null?"attachment":file.getOriginalFilename()).getFileName().toString();at.storedName=stored;at.contentType=type;at.sizeBytes=file.getSize();attachments.save(at);return Map.of("message","Attachment uploaded.","attachmentId",at.id);}
 @GetMapping("/attachments/{id}") public ResponseEntity<byte[]> getAttachment(@PathVariable Long id,HttpSession s)throws IOException{UserAccount u=current.require(s);AppointmentAttachment a=attachments.findById(id).orElseThrow();if(!a.appointment.customer.id.equals(u.id)&&!a.appointment.provider.user.id.equals(u.id)&&!u.role.equals("ADMIN"))throw new IllegalArgumentException("You are not allowed to view this attachment.");Path path=Paths.get(uploadDir).toAbsolutePath().normalize().resolve(a.storedName);byte[] bytes=Files.readAllBytes(path);return ResponseEntity.ok().contentType(MediaType.parseMediaType(a.contentType)).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+a.originalName.replace("\"","")+"\"").body(bytes);}
 @GetMapping("/provider/calendar") public List<Map<String,Object>> calendar(@RequestParam String from,@RequestParam String to,HttpSession s){ProviderProfile p=myProviderProfile(s);AvailabilitySettings set=booking.getSettings(p);LocalDate start=LocalDate.parse(from),end=LocalDate.parse(to);List<Map<String,Object>> out=new ArrayList<>();for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1)){List<Appointment> day=appointments.findByProviderIdAndStartAtBetween(p.id,d.atStartOfDay(),d.plusDays(1).atStartOfDay());long count=day.stream().filter(a->List.of("PENDING","APPROVED").contains(a.status)).count();String status=!set.workingDays.contains(d.getDayOfWeek().name())?"CL":count>=set.dailyCapacity?"F":count==0?"A":"NC";out.add(Map.of("date",d.toString(),"capacity",set.dailyCapacity,"booked",count,"remaining",Math.max(0,set.dailyCapacity-count),"status",status));}return out;}
 @GetMapping("/invoices/mine") public List<Map<String,Object>> myInvoices(HttpSession s){UserAccount u=current.require(s);List<Invoice> list=u.role.equals("PROVIDER")?invoices.findByAppointmentProviderIdOrderByIssuedAtDesc(myProviderProfile(s).id):invoices.findByAppointmentCustomerIdOrderByIssuedAtDesc(u.id);return list.stream().map(i->Map.of("id",i.id,"appointmentCode",i.appointment.verificationCode,"service",i.appointment.service.title,"amount",i.amount,"status",i.status,"issuedAt",i.issuedAt)).toList();}
 @PostMapping("/invoices/{id}/mark-paid") public Map<String,String> paid(@PathVariable Long id,HttpSession s){UserAccount u=current.requireRole(s,"PROVIDER");Invoice i=invoices.findById(id).orElseThrow();if(!i.appointment.provider.user.id.equals(u.id))throw new IllegalArgumentException("Not your invoice.");i.status="PAID";invoices.save(i);return Map.of("message","Invoice marked paid.");}
 @GetMapping("/admin/providers") public List<Map<String,Object>> pendingProviders(HttpSession s){current.requireRole(s,"ADMIN");return providers.findByVerificationStatusIgnoreCase("PENDING").stream().map(p->{Map<String,Object> v=providerView(p,null);v.put("documents",providerDocuments.findByProviderId(p.id).stream().map(d->Map.of("id",d.id,"name",d.originalName)).toList());return v;}).toList();}
 @PostMapping("/admin/providers/{id}/review") public Map<String,Object> review(@PathVariable Long id,@RequestBody DecisionRequest r,HttpSession s){current.requireRole(s,"ADMIN");ProviderProfile p=providers.findById(id).orElseThrow();String d=r.decision().toUpperCase();if(d.equals("VERIFIED")&&providerDocuments.findByProviderId(p.id).isEmpty())throw new IllegalArgumentException("Upload and review at least one verification document before approving this provider.");if(!List.of("VERIFIED","REJECTED","UNDER_REVIEW","RESUBMISSION_REQUIRED").contains(d))throw new IllegalArgumentException("Invalid verification decision.");p.verificationStatus=d;p.verificationNote=r.note();providers.save(p);return providerView(p,null);}
 @GetMapping("/admin/summary") public Map<String,Object> adminSummary(HttpSession s){current.requireRole(s,"ADMIN");return Map.of("users",users.count(),"providers",providers.count(),"services",offerings.count(),"appointments",appointments.count(),"pendingProviders",providers.findByVerificationStatusIgnoreCase("PENDING").size());}
 @Scheduled(fixedDelay=60000) public void expirePendingAppointments(){booking.expire();}
}
